#define _POSIX_C_SOURCE 200809L
#include "brvm.h"
#include "br_adapters.h"
#include <ctype.h>
#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
static uint16_t g16(const uint8_t*p){return(uint16_t)(p[0]|((uint16_t)p[1]<<8));}
static uint32_t g32(const uint8_t*p){return(uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static void p16(uint8_t*p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);}
static void p32(uint8_t*p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}
static int load(const char*path,uint8_t**d,size_t*n){FILE*f=fopen(path,"rb");long z;if(!f||fseek(f,0,SEEK_END)||(z=ftell(f))<0||fseek(f,0,SEEK_SET)){if(f)fclose(f);return-1;}*d=malloc((size_t)z+1);if(!*d){fclose(f);return-1;}*n=fread(*d,1,(size_t)z,f);if(fclose(f)||*n!=(size_t)z){free(*d);*d=NULL;return-1;}return 0;}
static int save(const char*p,const uint8_t*d,size_t n){FILE*f=fopen(p,"wb");if(!f)return-1;if(fwrite(d,1,n,f)!=n||fclose(f)){fclose(f);return-1;}return 0;}
static int vmp(br_vm*v,br_posix_ctx*c,const char*state){br_vm_config q={4096,64,64,BR_CAP_ALL,NULL,0};if(br_posix_adapter_init(c,state?state:"/tmp/brctl"))return-1;if(br_vm_create(v,&br_hal_posix,c)||br_vm_initialize(v)||br_vm_configure(v,&q))return-1;return 0;}
static int rawkey(const char*p,uint8_t k[32]){uint8_t*d;size_t n;if(load(p,&d,&n)||n!=32)return-1;memcpy(k,d,32);memset(d,0,n);free(d);return 0;}
static int keygen(const char*pr,const char*pu){EVP_PKEY_CTX*c=EVP_PKEY_CTX_new_id(EVP_PKEY_ED25519,NULL);EVP_PKEY*k=NULL;uint8_t a[32],b[32];size_t an=32,bn=32;int ok=c&&EVP_PKEY_keygen_init(c)==1&&EVP_PKEY_keygen(c,&k)==1&&EVP_PKEY_get_raw_private_key(k,a,&an)==1&&EVP_PKEY_get_raw_public_key(k,b,&bn)==1&&!save(pr,a,an)&&!chmod(pr,0600)&&!save(pu,b,bn);memset(a,0,sizeof(a));EVP_PKEY_free(k);EVP_PKEY_CTX_free(c);return ok?0:-1;}
static int signimg(const char*in,const char*out,const char*kp){uint8_t*d,*o,k[32],sig[64];size_t n,sn=64;EVP_PKEY*p=NULL;EVP_MD_CTX*c=NULL;int ok=0;if(load(in,&d,&n)||n<BR_IMAGE_HEADER||n+64>BR_UPDATE_BYTES||memcmp(d,"BRIM",4)||d[7]&2||rawkey(kp,k))return-1;d[7]|=2;p=EVP_PKEY_new_raw_private_key(EVP_PKEY_ED25519,NULL,k,32);c=EVP_MD_CTX_new();if(p&&c&&EVP_DigestSignInit(c,NULL,NULL,NULL,p)==1&&EVP_DigestSign(c,sig,&sn,d,n)==1&&sn==64){o=malloc(n+64);if(o){memcpy(o,d,n);memcpy(o+n,sig,64);ok=save(out,o,n+64)==0;free(o);}}memset(k,0,32);free(d);EVP_MD_CTX_free(c);EVP_PKEY_free(p);return ok?0:-1;}
static int verifyrun(const char*im,const char*kp,int run){uint8_t*d,k[32];size_t n;br_vm v;br_posix_ctx c;int rc;if(load(im,&d,&n)||rawkey(kp,k)||vmp(&v,&c,"/tmp/brctl-verify"))return-1;v.iv_=0;rc=br_image_load(&v,d,n,k,32,1);if(!rc&&run)rc=br_vm_run(&v,4096);if(!rc)printf("{\"iv_\":%u,\"bytes\":%zu,\"status\":%u,\"trap\":%u}\n",v.iv_,n,v.status,v.trap);br_vm_destroy(&v);free(d);return rc;}
static char*trim(char*s){char*e;while(isspace((unsigned char)*s))s++;e=s+strlen(s);while(e>s&&isspace((unsigned char)e[-1]))*--e=0;return s;}
static int inspect(const char*p){uint8_t*d;size_t n;if(load(p,&d,&n)||n<BR_IMAGE_HEADER||memcmp(d,"BRIM",4))return-1;printf("{\"format\":\"BRIM/1\",\"version\":%u,\"requested_caps\":%u,\"instructions\":%u,\"data_bytes\":%u,\"signed\":%s,\"bytes\":%zu}\n",g32(d+16),g32(d+20),g16(d+28),g16(d+30),(d[7]&2)?"true":"false",n);free(d);return 0;}
static int update(const char*im,const char*kp,const char*state){uint8_t*d,k[32],req[BR_FRAGMENT_BYTES+12],rsp[16];size_t n,pos=0,z;uint16_t seq=0;br_vm v;br_posix_ctx c;uint32_t tx=1;int rc=0;if(load(im,&d,&n)||n>BR_UPDATE_BYTES||rawkey(kp,k)||vmp(&v,&c,state))return-1;br_vm_set_ik_(&v,k,32);if(!br_vm_recover(&v))tx=v.last_txid+1;else{br_vm_reset(&v,1);v.trap=0;}while(pos<n){z=n-pos;if(z>BR_FRAGMENT_BYTES)z=BR_FRAGMENT_BYTES;memset(req,0,12);req[0]=1;req[1]=BR_APDU_UPDATE;req[2]=(pos+z<n)?1:0;p32(req+4,tx);p16(req+8,seq++);p16(req+10,(uint16_t)z);memcpy(req+12,d+pos,z);if(br_apdu(&v,req,z+12,rsp,sizeof(rsp))!=8||(!req[2]&&(rsp[0]!=0x90||rsp[1]!=0))||(req[2]&&rsp[0]!=0x61)){rc=-1;break;}pos+=z;}if(!rc)printf("{\"update\":\"PASS\",\"version\":%u,\"generation\":%u}\n",v.iv_,v.pg_);br_vm_destroy(&v);memset(k,0,32);free(d);return rc;}
static int statecmd(const char*cmd,const char*p,const char*key){br_vm v;br_posix_ctx c;uint8_t k[32];int rc;if(vmp(&v,&c,p))return-1;if(!strcmp(cmd,"save-state"))rc=br_vm_save(&v);else{if(key&&(!rawkey(key,k)))br_vm_set_ik_(&v,k,32);rc=br_vm_recover(&v);if(!rc)printf("{\"generation\":%u,\"iv_\":%u,\"txid\":%u,\"slot\":%u}\n",v.pg_,v.iv_,v.last_txid,v.as_);}br_vm_destroy(&v);return rc;}
static int serve(const char*state,const char*key){br_vm v;br_posix_ctx c;uint8_t k[32],req[BR_UPDATE_BYTES+12],rsp[1024];char line[(BR_UPDATE_BYTES+12)*2+4];size_t n,r,i;if(vmp(&v,&c,state))return-1;if(key&&!rawkey(key,k))br_vm_set_ik_(&v,k,32);if(br_vm_recover(&v)){br_vm_reset(&v,1);v.trap=0;}while(fgets(line,sizeof(line),stdin)){char*x=trim(line);n=strlen(x);if(n&1||n/2>sizeof(req)){puts("ERR");continue;}for(i=0;i<n/2;i++){unsigned y;if(sscanf(x+2*i,"%2x",&y)!=1)break;req[i]=(uint8_t)y;}if(i!=n/2){puts("ERR");continue;}r=br_apdu(&v,req,n/2,rsp,sizeof(rsp));if(!r){puts("ERR");continue;}for(i=0;i<r;i++)printf("%02x",rsp[i]);putchar('\n');fflush(stdout);}br_vm_destroy(&v);return 0;}
static int runplain(const char*p){uint8_t*d;size_t n;br_vm v;int rc;if(load(p,&d,&n)||br_vm_init(&v))return-1;v.iv_=0;rc=br_image_load(&v,d,n,NULL,0,0);if(!rc)rc=br_vm_run(&v,4096);printf("{\"status\":%u,\"trap\":%u,\"R2\":%llu}\n",v.status,v.trap,(unsigned long long)br_vm_reg(&v,2)[0]);br_vm_destroy(&v);free(d);return rc;}
int main(int ac,char**av){int rc=-1;if(ac==2&&!strcmp(av[1],"selftest"))rc=br_core_selftest();else if(ac==3&&!strcmp(av[1],"run"))rc=runplain(av[2]);else if(ac==3&&!strcmp(av[1],"inspect-image"))rc=inspect(av[2]);else if(ac==4&&!strcmp(av[1],"keygen"))rc=keygen(av[2],av[3]);else if(ac==5&&!strcmp(av[1],"sign-image"))rc=signimg(av[2],av[3],av[4]);else if(ac==4&&!strcmp(av[1],"verify-image"))rc=verifyrun(av[2],av[3],0);else if(ac==4&&!strcmp(av[1],"run-signed"))rc=verifyrun(av[2],av[3],1);else if(ac==6&&!strcmp(av[1],"update")&&!strcmp(av[4],"--state"))rc=update(av[2],av[3],av[5]);else if(ac==3&&!strcmp(av[1],"save-state"))rc=statecmd(av[1],av[2],NULL);else if((ac==3||ac==4)&&!strcmp(av[1],"recover-state"))rc=statecmd(av[1],av[2],ac==4?av[3]:NULL);else if(ac==4&&!strcmp(av[1],"status")&&!strcmp(av[2],"--state"))rc=statecmd("status",av[3],NULL);else if((ac==4||ac==5)&&!strcmp(av[1],"serve")&&!strcmp(av[2],"--state"))rc=serve(av[3],ac==5?av[4]:NULL);else fprintf(stderr,"brctl selftest|run IMG|inspect-image IMG|keygen PRIV PUB|sign-image IN OUT PRIV|verify-image IMG PUB|run-signed IMG PUB|update IMG PUB --state PREFIX|save-state PREFIX|recover-state PREFIX [PUB]|status --state PREFIX|serve --state PREFIX [PUB]\n");return rc?1:0;}
